import java.util.*;import java.util.zip.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;
public final class InspectSiteDateConsumers {
 public static void main(String[]args)throws Exception{try(var zip=new ZipFile(args[0])){for(var entry:Collections.list(zip.entries()))if(entry.getName().matches("classes[0-9]*\\.dex"))try(var in=zip.getInputStream(entry)){var dex=new DexBackedDexFile(Opcodes.getDefault(),java.nio.ByteBuffer.wrap(in.readAllBytes()));for(ClassDef type:dex.getClasses())for(Method method:type.getMethods())if(method.getImplementation()!=null){boolean row=false,date=false;for(Instruction instruction:method.getImplementation().getInstructions()){String ref=instruction instanceof ReferenceInstruction r?r.getReference().toString():"";row|=ref.equals("Lo/setSkipText;->d:J");date|=ref.contains("DateUtils")||ref.contains("DateFormat")||ref.contains("Ljava/util/Date;")||instruction.getOpcode()==Opcode.MUL_LONG||instruction.getOpcode()==Opcode.MUL_LONG_2ADDR;}if(row&&date)System.out.println(method);}}}}
}
